export const ADMIN_KNOWLEDGE_LIBRARY_CONTRACT = "ARCTOR_ADM4K1_ADMIN_LIBRARY_READ_ONLY_V1";
export const adminKnowledgeDocuments: readonly AdminKnowledgeDoc[] = documents;

// Future executor contract; NO current caller and all documents disabled for agents.
// Never use this function as a substitute for authorization and explicit approval.
export function selectApprovedKnowledgeBriefs(input: { roleCode: string; taskCode: string }):
  readonly { id: string; version: string; brief: string }[] {
  return documents.filter((doc) => doc.approvalStatus === "approved" && doc.agentEnabled &&
    doc.roleCodes.includes(input.roleCode) && doc.taskCodes.includes(input.taskCode))
    .map((doc) => ({ id: doc.id, version: doc.version, brief: doc.agentBrief }));
}
